const fs = require('fs');

const arquivo = '/home/x1/Music/teste.txt';

// Le o conteudo atual (se o arquivo nao existir, comeca vazio)
let texto = '';
if (fs.existsSync(arquivo)) {
  texto = fs.readFileSync(arquivo, 'utf8');
}

// Numero de linhas existentes (ignora o \n final)
let linhas = 0;
if (texto.length > 0) {
  linhas = texto.replace(/\n$/, '').split('\n').length;
}

const numeroDaLinha = linhas + 1;

// Garante que a nova linha comece em uma linha propria
const prefixo = texto.length > 0 && !texto.endsWith('\n') ? '\n' : '';

// Cria o arquivo se necessario (append)
fs.appendFileSync(arquivo, prefixo + numeroDaLinha + '\n', 'utf8');

return [{
  json: {
    arquivo,
    numeroDaLinha,
    mensagem: `Linha ${numeroDaLinha} inserida em ${arquivo}`,
  },
}];
